/* JPT PARTNER VISUAL LAYER FINAL V1
   VISUAL ONLY. Existing business/database/order/menu functions remain untouched.
*/
(function(){
'use strict';
if(window.__JPT_PARTNER_VISUAL_LAYER_FINAL_V1__) return;
window.__JPT_PARTNER_VISUAL_LAYER_FINAL_V1__=true;

const LOGO='data:image/png;base64,';
const POSTER='data:image/jpeg;base64,';
const ROOT='jptVisualHomeFinalV1';

const css=`
#ROOT{
  background:#050505;color:#fff;max-width:1100px;margin:0 auto;
  padding:10px 10px 105px;min-height:70vh;display:none
}
#ROOT .vf-head{display:flex;align-items:center;gap:10px;padding:6px 2px 10px}
#ROOT .vf-menu{width:64px;height:64px;border:1px solid #735719;border-radius:18px;display:grid;place-items:center;color:#efc64d;font-size:32px}
#ROOT .vf-logo{width:64px;height:64px;border-radius:50%;border:2px solid #e7bd42;box-shadow:0 0 14px rgba(231,189,66,.45)}
#ROOT .vf-brand{min-width:0;flex:1}
#ROOT .vf-brand b{display:block;color:#f2c84f;font-size:20px;font-weight:1000}
#ROOT .vf-brand span{display:block;color:#aaa;font-size:11px;letter-spacing:1px;margin-top:2px}
#ROOT .vf-bell{width:64px;height:64px;border:1px solid #735719;border-radius:18px;background:#080808;color:#f2c84f;font-size:30px}
#ROOT .vf-context{text-align:center;color:#f0c64d;font-weight:900;margin:0 0 8px}
#ROOT .vf-outlet{width:100%;height:58px;background:#080808;color:#f2c84f;border:2px solid #dcb13c;border-radius:18px;padding:0 16px;font-weight:900;font-size:18px;box-shadow:0 0 14px rgba(220,177,60,.20)}
#ROOT .vf-poster{position:relative;height:190px;margin:12px 0 16px;border:2px solid #d9ad35;border-radius:20px;overflow:hidden;box-shadow:0 0 16px rgba(238,190,55,.28)}
#ROOT .vf-poster img{width:100%;height:100%;object-fit:cover;display:block}
#ROOT .vf-status{display:flex;align-items:center;gap:13px;min-height:130px;padding:16px;border:2px solid #00ff62;border-radius:20px;background:#06160b;box-shadow:0 0 12px #00ff62,0 0 34px rgba(0,255,98,.50),inset 0 0 30px rgba(0,255,98,.10);transition:.25s}
#ROOT .vf-status.offline{border-color:#ff2638;background:#160506;box-shadow:0 0 12px #ff2638,0 0 34px rgba(255,38,56,.50),inset 0 0 30px rgba(255,38,56,.10)}
#ROOT .vf-status img{width:78px;height:78px;border-radius:50%;border:2px solid #e7bd42;box-shadow:0 0 10px #e7bd42}
#ROOT .vf-status-main{flex:1;min-width:0}
#ROOT .vf-status-title{font-size:22px;font-weight:1000;color:#62ff9a}
#ROOT .vf-status.offline .vf-status-title{color:#ff6976}
#ROOT .vf-status-sub{color:#ddd;margin-top:4px;font-size:12px}
#ROOT .vf-status-btn{background:#090909;color:#f2c84f;border:1px solid #b98a24;border-radius:12px;padding:10px;font-weight:900}
#ROOT .vf-title{display:flex;justify-content:space-between;align-items:center;margin:16px 3px 9px}
#ROOT .vf-title b{color:#f0c64d;font-size:19px}
#ROOT .vf-title span{color:#777;font-size:11px}
#ROOT .vf-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}
#ROOT .vf-metric{min-height:96px;border:1.25px solid #18c95c;border-radius:16px;text-align:center;padding:13px 5px;background:linear-gradient(145deg,#092214,#06140c 60%,#040806);box-shadow:inset 0 0 16px rgba(0,255,98,.08),0 0 9px rgba(0,255,98,.14)}
#ROOT .vf-num{font-size:29px;font-weight:1000;color:#70ff9e}
#ROOT .vf-label{font-size:10px;color:#c9ddd0;margin-top:6px}
#ROOT .vf-actions{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}
#ROOT .vf-action{min-height:86px;border:1.25px solid #efc33e;border-radius:15px;background:linear-gradient(145deg,#241b05,#0b0904);color:#fff;font-weight:900;font-size:11px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:5px;box-shadow:inset 0 0 15px rgba(232,184,47,.11),0 0 11px rgba(232,184,47,.25)}
#ROOT .vf-action b{font-size:25px;color:#f7ce51}
#ROOT .vf-bottom{position:fixed;left:10px;right:10px;bottom:10px;z-index:9999;background:#050505;border:2px solid #efc43f;border-radius:20px;padding:7px;display:grid;grid-template-columns:repeat(5,1fr);box-shadow:0 0 20px #000,0 0 22px rgba(239,196,63,.50)}
#ROOT .vf-bottom button{border:0;background:transparent;color:#aaa;border-radius:14px;padding:8px 2px;font-size:9px;font-weight:900}
#ROOT .vf-bottom button.active{background:#f2c64d;color:#111;box-shadow:0 0 14px rgba(242,198,77,.48)}
#ROOT .vf-bottom b{display:block;font-size:19px;margin-bottom:2px}
@media(max-width:760px){
 #ROOT .vf-metrics{grid-template-columns:repeat(2,1fr)}
 #ROOT .vf-actions{grid-template-columns:repeat(4,1fr)}
 #ROOT .vf-logo,#ROOT .vf-menu,#ROOT .vf-bell{width:58px;height:58px}
 #ROOT .vf-brand b{font-size:18px}
}
`;
function addStyle(){
 if(!document.getElementById('jptVisualHomeFinalV1Style')){
  const s=document.createElement('style');
  s.id='jptVisualHomeFinalV1Style';s.textContent=css;document.head.appendChild(s);
 }
}
function esc(v){return String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function homeActive(){const a=document.querySelector('.panel.active');return !a||a.id==='home';}
function val(id){return document.getElementById(id)?.textContent?.trim()||'—';}
function outlet(){
 const s=document.getElementById('outletSelect'),o=s?.options?.[s.selectedIndex];
 return {code:s?.value||window.activeOutlet||localStorage.getItem('jpt_admin_outlet')||'JPT-001',name:o?.textContent?.trim()||'Jeet Punjabi Tadka'};
}
function root(){
 let r=document.getElementById(ROOT);
 if(!r){r=document.createElement('div');r.id=ROOT;document.querySelector('main.shell')?.prepend(r);}
 return r;
}
function build(){
 const r=root(),o=outlet();
 r.innerHTML=`
 <div class="vf-head"><div class="vf-menu">☰</div><img class="vf-logo" src="${LOGO}"><div class="vf-brand"><b>${esc(o.name)}</b><span>RESTAURANT PARTNER APP • ${esc(o.code)}</span></div><button class="vf-bell" id="vfBell">🔔</button></div>
 <div class="vf-context">${esc(o.name)} • ${esc(o.code)}</div>
 <select class="vf-outlet" id="vfOutlet"></select>
 <div class="vf-poster"><img src="${POSTER}" alt="Chole Bhature"></div>
 <div class="vf-status" id="vfStatus"><img src="${LOGO}"><div class="vf-status-main"><div class="vf-status-title" id="vfStatusTitle">RESTAURANT IS ONLINE</div><div class="vf-status-sub" id="vfStatusSub">Orders incoming</div></div><button class="vf-status-btn" id="vfStatusBtn">Mark Offline</button></div>
 <div class="vf-title"><b>Today at your outlet</b><span>LIVE</span></div>
 <div class="vf-metrics"><div class="vf-metric"><div class="vf-num" id="vfOrders">—</div><div class="vf-label">🧾 Orders Today</div></div><div class="vf-metric"><div class="vf-num" id="vfMenu">—</div><div class="vf-label">🍽️ Menu Items</div></div><div class="vf-metric"><div class="vf-num" id="vfOffers">—</div><div class="vf-label">🏷️ Active Offers</div></div><div class="vf-metric"><div class="vf-num" id="vfCampaigns">—</div><div class="vf-label">📣 Campaigns</div></div></div>
 <div class="vf-title"><b>Quick Actions</b><span>Manage your restaurant</span></div>
 <div class="vf-actions"><button class="vf-action" data-p="orders"><b>🧾</b>Orders</button><button class="vf-action" data-p="menu"><b>🍽️</b>Menu Manager</button><button class="vf-action" data-p="images"><b>🖼️</b>Images</button><button class="vf-action" data-p="offers"><b>🏷️</b>Offers</button><button class="vf-action" data-p="campaigns"><b>📣</b>Campaigns</button><button class="vf-action" data-p="finance"><b>▥</b>Finance</button><button class="vf-action" data-p="reports"><b>▤</b>Reports</button><button class="vf-action" data-p="settings"><b>⚙️</b>Settings</button></div>
 <div class="vf-bottom"><button class="active" data-p="home"><b>⌂</b>Home</button><button data-p="orders"><b>🧾</b>Orders</button><button data-p="menu"><b>☰</b>Menu</button><button data-p="offers"><b>🏷️</b>Offers</button><button data-p="settings"><b>⚙️</b>Settings</button></div>`;
 const old=document.getElementById('outletSelect'),ns=document.getElementById('vfOutlet');
 if(old&&ns){ns.innerHTML=old.innerHTML;ns.value=old.value;ns.onchange=()=>{old.value=ns.value;old.dispatchEvent(new Event('change',{bubbles:true}));};}
 r.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{if(typeof window.showPanel==='function')window.showPanel(b.dataset.p);setTimeout(syncVisibility,40);});
 document.getElementById('vfBell')?.addEventListener('click',()=>{if(typeof window.showPanel==='function')window.showPanel('orders');setTimeout(syncVisibility,40);});
 document.getElementById('vfStatusBtn')?.addEventListener('click',()=>{document.getElementById('statusToggle')?.click();setTimeout(sync,300);});
 sync();
}
function sync(){
 const r=document.getElementById(ROOT);if(!r)return;
 document.getElementById('vfOrders').textContent=val('ordersCount');
 document.getElementById('vfMenu').textContent=val('menuCount');
 document.getElementById('vfOffers').textContent=val('offerCount');
 document.getElementById('vfCampaigns').textContent=val('campaignCount');
 const s=document.getElementById('statusBox'),on=!!s&&s.classList.contains('online'),v=document.getElementById('vfStatus');
 v?.classList.toggle('offline',!on);
 document.getElementById('vfStatusTitle').textContent=on?'RESTAURANT IS ONLINE':'RESTAURANT IS OFFLINE';
 document.getElementById('vfStatusSub').textContent=(document.getElementById('statusText')?.textContent||'Orders incoming').trim();
 document.getElementById('vfStatusBtn').textContent=on?'Mark Offline':'Mark Online';
}
function syncVisibility(){
 const r=document.getElementById(ROOT);if(!r)return;
 const home=homeActive();r.style.display=home?'block':'none';
 const els=[document.querySelector('.top'),document.querySelector('.tabs'),document.getElementById('hero'),document.querySelector('.grid')];
 els.forEach(e=>{if(e)e.style.removeProperty('display');});
 if(home)els.forEach(e=>{if(e)e.style.display='none';});
 r.querySelectorAll('.vf-bottom button').forEach(b=>b.classList.toggle('active',b.dataset.p==='home'&&home));
 sync();
}
function removeOldVisualOnly(){
 document.querySelectorAll('#jptFinalTouchHomeV10,#jptV10Bottom,#jptV13OutletWrap,#jptV13OutletPopup,#jptV13OutletBackdrop,[class*="jpt-v9-bottom"],[class*="jpt-v10-bottom"]').forEach(e=>e.remove());
}
function boot(){
 addStyle();removeOldVisualOnly();build();syncVisibility();
 setTimeout(syncVisibility,1800);setTimeout(syncVisibility,3500);setInterval(sync,1200);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
